import 'package:flutter/material.dart';import 'package:pos_app/core/app_services.dart';import 'package:pos_app/features/cloud_admin/data/cloud_admin_repository.dart';
class CloudAdminScreen extends StatefulWidget{const CloudAdminScreen({super.key});@override State<CloudAdminScreen> createState()=>_CloudAdminScreenState();}class _CloudAdminScreenState extends State<CloudAdminScreen>{late final repo=CloudAdminRepository(cloudApiClient);@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Administración remota'),actions:[IconButton(onPressed:_invite,icon:const Icon(Icons.devices))]),body:ListView(padding:const EdgeInsets.all(16),children:[FutureBuilder<Map<String,Object?>>(future:repo.dashboard(),builder:(c,s)=>Card(child:ListTile(title:const Text('Dashboard cloud'),subtitle:Text(s.hasData?s.data.toString():'Cargando...')))),for(final e in {'Ventas':'/api/sales','Productos':'/api/products','Categorías':'/api/categories','Proveedores':'/api/suppliers','Inventario':'/api/inventory','Lotes':'/api/inventory/lots','Compras':'/api/purchases','Gastos':'/api/expenses','Caja':'/api/cash','Usuarios':'/api/users'}.entries)Card(child:ListTile(title:Text(e.key),trailing:const Icon(Icons.chevron_right),onTap:()=>_show(e.key,e.value))) ]));Future<void> _show(String title,String path) async {try{final items=await repo.list(path);if(!mounted)return;await showDialog<void>(context:context,builder:(d)=>AlertDialog(title:Text(title),content:SizedBox(width:650,height:450,child:ListView.builder(itemCount:items.length,itemBuilder:(_,i)=>ListTile(title:Text(items[i].toString())))),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Cerrar'))]));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('No fue posible consultar la nube.')));}}Future<void> _invite() async {try{final j=await repo.createInvitation();if(!mounted)return;await showDialog<void>(context:context,builder:(d)=>AlertDialog(title:const Text('Código de invitación'),content:SelectableText('${j['code'] ?? j['invitationCode']}
Expira: ${j['expiresAt']}'),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Cerrar'))]));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('No fue posible generar la invitación.')));}}}
